import dragonfly


# Define grammar for smart home voice commands
class SmartHomeGrammar(dragonfly.Grammar):

    def __init__(self):
        super(SmartHomeGrammar, self).__init__(name="smart_home")

        self.light_rule = dragonfly.MappingRule(
            mapping={
                "lights on": "turn on lights",
                "lights off": "turn off lights"
            }
        )

        self.thermostat_rule = dragonfly.MappingRule(
            mapping={
                "warmer": "increase temperature",
                "cooler": "decrease temperature"
            }
        )

        self.security_rule = dragonfly.MappingRule(
            mapping={
                "security on": "activate security system",
                "security off": "deactivate security system"
            }
        )

        self.add_rule(self.light_rule)
        self.add_rule(self.thermostat_rule)
        self.add_rule(self.security_rule)


def start_listening():
    engine = dragonfly.get_engine()
    smart_home_grammar = SmartHomeGrammar()
    smart_home_grammar.load()
    engine.mimic("start listening")
    engine.do_action(lambda: dragonfly.get_engine().recognize_forever())

start_listening()
