import speech_recognition as sr
import pyttsx3

# Initialize the recognizer and engine
recognizer = sr.Recognizer()
engine = pyttsx3.init()

# Listen for specific voice commands
def listen_for_commands():
    with sr.Microphone() as source:
        print("Listening...")
        audio = recognizer.listen(source)

    try:
        command = recognizer.recognize_google(audio).lower()
        print("Recognized command:", command)
        process_command(command)
    except sr.UnknownValueError:
        print("Could not understand the audio")
    except sr.RequestError:
        print("Could not request results; check your internet connection")

# Process and recognize spoken instructions
def process_command(command):
    if "lights on" in command:
        turn_on_lights()
    elif "lights off" in command:
        turn_off_lights()
    elif "warmer" in command:
        increase_temperature()
    elif "cooler" in command:
        decrease_temperature()
    elif "security on" in command:
        activate_security_system()
    elif "security off" in command:
        deactivate_security_system()

# Functions for controlling smart home devices
def turn_on_lights():
    print("Turning on the lights")

def turn_off_lights():
    print("Turning off the lights")

def increase_temperature():
    print("Increasing the temperature")

def decrease_temperature():
    print("Decreasing the temperature")

def activate_security_system():
    print("Activating the security system")

def deactivate_security_system():
    print("Deactivating the security system")

# Start listening for voice commands
listen_for_commands()
